function datePickerPresetRanges(){
  function dayOffset(days){var d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+days);return d;}
  function sameDayRange(days){var d=dayOffset(days);return [d,new Date(d.getTime())];}
  return [
    {label:'今天',value:function(){return sameDayRange(0);}},
    {label:'昨天',value:function(){return sameDayRange(-1);}},
    {label:'上周',value:function(){var today=dayOffset(0),day=today.getDay()||7,end=new Date(today.getTime());end.setDate(today.getDate()-day);var begin=new Date(end.getTime());begin.setDate(end.getDate()-6);return [begin,end];}},
    {label:'本月',value:function(){var today=dayOffset(0);return [new Date(today.getFullYear(),today.getMonth(),1),new Date(today.getFullYear(),today.getMonth()+1,0)];}},
    {label:'过去7天',value:function(){return [dayOffset(-6),dayOffset(0)];}},
    {label:'过去15天',value:function(){return [dayOffset(-14),dayOffset(0)];}},
    {label:'过去30天',value:function(){return [dayOffset(-29),dayOffset(0)];}}
  ];
}
